    for (int i = 0; i < n; i++) scanf("%d", &d[i]);

    for (int start_len = 1; start_len <= n; start_len++) {
        if (d[0] == 0) continue;

        char value[1005];
        int len = start_len;
        for (int i = 0; i < len; i++) value[i] = (char)('0' + d[i]);

        int pos = 0;
        int valid = 1;

        while (pos < n) {
            if (pos + len > n) {
                valid = 0;
                break;
            }

            for (int i = 0; i < len; i++) {
                if (value[i] != (char)('0' + d[pos + i])) {
                    valid = 0;
                    break;
                }
            }
            if (!valid) break;

            pos += len;
            if (pos == n) break;

            int i = len - 1;
            while (i >= 0 && value[i] == '9') {
                value[i] = '0';
                i--;
            }
            if (i >= 0) {
                value[i]++;
            } else {
                for (int j = len; j > 0; j--) value[j] = value[j - 1];
                value[0] = '1';
